"""CPU-only masks/transport fixtures, not generated by Wan/SAM2."""
import base64
from fractions import Fraction
import io
import json
from pathlib import Path
import shutil
import subprocess
import tempfile
import unittest
import zipfile
from PIL import Image,ImageDraw
from frame_studio import target_masks as target
from frame_studio.wan_bridge import prepare,finish,generation_hashes,temporal_mapping


def encoded_mask(mask):
    buf=io.BytesIO();mask.save(buf,'PNG');return base64.b64encode(buf.getvalue()).decode()


class TargetTests(unittest.TestCase):
    def setUp(self):
        self.tmp=tempfile.TemporaryDirectory();self.addCleanup(self.tmp.cleanup);self.work=Path(self.tmp.name)
        self.manifest={'schema':'vos-frame-studio/1','source':{'width':64,'height':40},
            'frames':[{'file':f'frame_{n}.png','timestamp':str(Fraction(n,30))} for n in range(3)]}
        (self.work/'manifest.json').write_text(json.dumps(self.manifest))
        for n in range(3):
            im=Image.new('RGB',(64,40),'gray');draw=ImageDraw.Draw(im)
            draw.rectangle((5+n,10,15+n,30),fill='red');draw.rectangle((45,10,55,30),fill='green');im.save(self.work/f'frame_{n}.png')
        target.save_selection(self.work,{'name':'Wanda (fixture)','keyframes':{'0':{'points':[[.15,.5,1],[.8,.5,0]]}}})
        (self.work/'target_masks').mkdir()
        for n in range(3):self.mask(n).save(target.mask_path(self.work,n))

    def mask(self,n=0,other=False):
        im=Image.new('L',(64,40));ImageDraw.Draw(im).rectangle((45,10,55,30) if other else (5+n,10,15+n,30),fill=255);return im

    def test_explicit_target_negative_point_and_full_review_required(self):
        self.assertFalse(target.audit(self.work)['issues'])
        with self.assertRaisesRegex(ValueError,'cada quadro'):target.approve(self.work,[0,2])
        target.approve(self.work,[0,1,2]);target.require_review(self.work)
        self.mask(1,other=True).save(target.mask_path(self.work,1))
        with self.assertRaises(ValueError):target.require_review(self.work)
        with self.assertRaisesRegex(ValueError,'Rastreamento suspeito'):target.approve(self.work,[0,1,2])
        self.assertIn(1,[i['frame'] for i in target.audit(self.work)['issues']])

    def test_correction_is_exact_frame_and_can_seed_sam2(self):
        self.mask(1,other=True).save(target.mask_path(self.work,1))
        other_before=target.digest(target.mask_path(self.work,2))
        target.apply_corrections(self.work,{'1':encoded_mask(self.mask(1))})
        self.assertEqual(other_before,target.digest(target.mask_path(self.work,2)))
        self.assertTrue((self.work/'target_seeds/frame_000001.png').is_file())
        target.approve(self.work,[0,1,2]);target.require_review(self.work)
        payload=target.editor_payload(self.work,'review')
        self.assertEqual(len(payload['images']),3);self.assertEqual(len(payload['masks']),3)
        self.assertEqual(payload['timestamps'],['0','1/30','1/15'])

    def test_wrong_actor_even_on_first_frame_is_blocked_by_anchors(self):
        self.mask(0,other=True).save(target.mask_path(self.work,0))
        report=target.audit(self.work)
        self.assertIn('mascara contradiz ponto positivo/negativo',report['frames'][0]['issues'])
        with self.assertRaises(ValueError):target.approve(self.work,[0,1,2])

    def test_missing_extra_wrong_resolution_gray_and_other_manifest_rejected(self):
        for mask in (Image.new('L',(32,40)),Image.new('L',(64,40),128),Image.new('RGBA',(64,40),(255,255,255,0))):
            with self.subTest(size=mask.size,mode=mask.mode):
                with self.assertRaises(ValueError):target.apply_corrections(self.work,{'1':encoded_mask(mask)})
        target.mask_path(self.work,1).unlink()
        with self.assertRaises(ValueError):target.signature(self.work)
        self.mask(1).save(target.mask_path(self.work,1));(self.work/'target_masks/extra.txt').touch()
        with self.assertRaises(ValueError):target.signature(self.work)
        (self.work/'target_masks/extra.txt').unlink()
        self.manifest['frames'][1]['timestamp']='9';(self.work/'manifest.json').write_text(json.dumps(self.manifest))
        with self.assertRaisesRegex(ValueError,'outro manifesto'):target.config(self.work)

    def test_changed_target_clears_old_seed_and_generation(self):
        target.apply_corrections(self.work,{'1':encoded_mask(self.mask(1))})
        (self.work/'generation.json').write_text('{}')
        target.save_selection(self.work,{'keyframes':{'0':{'points':[[.8,.5,1],[.15,.5,0]]}}})
        self.assertFalse((self.work/'generation.json').exists());self.assertFalse((self.work/'target_seeds').exists())

    def test_review_backup_preserves_native_masks_and_manifest(self):
        with self.assertRaises(ValueError):target.export_review(self.work,self.work/'review.zip')
        target.approve(self.work,[0,1,2]);backup=target.export_review(self.work,self.work/'review.zip')
        with zipfile.ZipFile(backup) as z:
            self.assertEqual(z.read('manifest.json'),(self.work/'manifest.json').read_bytes())
            for n in range(3):self.assertEqual(z.read(f'target_masks/frame_{n:06d}.png'),target.mask_path(self.work,n).read_bytes())
            self.assertIn('NAO importar',z.read('LEIA.txt').decode())

    def test_no_mask_interpolation_in_temporal_map(self):
        for fps in (24,30,60):
            starts=[Fraction(n,fps) for n in range(fps)]
            mapping=temporal_mapping(starts,[Fraction(1,fps)]*fps,Fraction(1))
            self.assertEqual(len(mapping['wan_to_native']),30)
            self.assertEqual(len(mapping['native_to_wan']),fps)
            self.assertTrue(all(0<=n<fps for n in mapping['wan_to_native']))
            self.assertTrue(all(Fraction(e)<=Fraction(1,60) for e in mapping['native_midpoint_error_seconds']))
        mapping=temporal_mapping([Fraction(0),Fraction(1,24)],[Fraction(1,24)]*2,Fraction(1,12))
        self.assertEqual(len(mapping['wan_to_native']),3) # tail selection/repetition, never interpolated


@unittest.skipUnless(shutil.which('ffmpeg') and shutil.which('ffprobe'),'FFmpeg required')
class NativeTargetRoundtripTests(unittest.TestCase):
    def test_two_people_native_masks_zip_import_mp4_at_24_30_60(self):
        from frame_studio.tests.helpers import create_project,package,import_zip,job_for
        from frame_studio.storage import sha256
        from frame_studio.probe import probe_project
        from frame_studio.timeline import scenes_for,native_timeline
        from frame_studio.packages import apply_import
        from frame_studio.render import build_video
        for fps in (24,30,60):
            with self.subTest(fps=fps),tempfile.TemporaryDirectory() as temporary:
                root=Path(temporary);store,project=create_project(root,rate=str(fps),audio=False)
                native=root/'people';native.mkdir()
                for n in range(18):
                    im=Image.new('RGB',(160,96),(30,30,40));draw=ImageDraw.Draw(im)
                    draw.rectangle((20+n,20,40+n,70),fill=(220,30,30));draw.rectangle((110,20,135,70),fill=(30,210,30));im.save(native/f'frame_{n:06d}.png')
                source=store.path(project['id'])/'source.media'
                subprocess.run(['ffmpeg','-v','error','-y','-framerate',str(fps),'-i',str(native/'frame_%06d.png'),'-c:v','libx264','-pix_fmt','yuv420p','-f','mp4',str(source)],check=True)
                project['source_sha256']=sha256(source);probe_project(store,project,job_for(store,project))
                project['scenes']=scenes_for(project['frames'],Fraction(project['source']['duration']),[6,12]);project['timeline']=native_timeline(project);store.save(project)
                archive=package(store,project,{'scope':'scene','scene_id':'scene_002'})
                ref=root/'ref.png';Image.new('RGB',(160,96),'blue').save(ref)
                work=root/'job';prepare(archive,ref,work)
                target.save_selection(work,{'name':'Left actor','keyframes':{'0':{'points':[[.2,.5,1],[.8,.5,0]]}}})
                (work/'target_masks').mkdir()
                for n in range(6):
                    mask=Image.new('L',(160,96));ImageDraw.Draw(mask).rectangle((26+n,20,46+n,70),fill=255);mask.save(target.mask_path(work,n))
                target.approve(work,list(range(6)))
                count=json.loads((work/'bridge.json').read_text())['frame_count'];stage=work/'wan_processed';stage.mkdir()
                subprocess.run(['ffmpeg','-v','error','-y','-f','lavfi','-i','color=c=blue:s=160x96:r=30','-frames:v',str(count),'-c:v','libx264',str(work/'wan_generated.mp4')],check=True)
                # Coarser Wan mask deliberately differs. Native mask must control composition.
                broad=Image.new('RGB',(160,96));ImageDraw.Draw(broad).rectangle((10,10,90,80),fill='white');broad.save(root/'broad.png')
                subprocess.run(['ffmpeg','-v','error','-y','-loop','1','-framerate','30','-i',str(root/'broad.png'),'-frames:v',str(count),'-c:v','libx264','-pix_fmt','yuv420p',str(stage/'src_mask.mp4')],check=True)
                (work/'generation.json').write_text(json.dumps(generation_hashes(work))) # explicit synthetic fixture receipt, not inference
                output=root/'edited.zip';finish(work,output)
                with zipfile.ZipFile(archive) as before,zipfile.ZipFile(output) as after:
                    self.assertEqual(before.read('manifest.json'),after.read('manifest.json'))
                    self.assertEqual(set(before.namelist()),set(after.namelist()))
                    manifest=json.loads(before.read('manifest.json'))
                    for n,f in enumerate(manifest['frames']):
                        a=Image.open(io.BytesIO(before.read(f['file']))).convert('RGB');b=Image.open(io.BytesIO(after.read(f['file']))).convert('RGB');mask=target.load_mask(target.mask_path(work,n),a.size)
                        for y in range(a.height):
                            for x in range(a.width):
                                if mask.getpixel((x,y))==0:self.assertEqual(a.getpixel((x,y)),b.getpixel((x,y)))
                        self.assertNotEqual(a.getpixel((35+n,40)),b.getpixel((35+n,40)))
                iid,report=import_zip(store,project,output);self.assertTrue(report['valid'],report['issues'])
                apply_import(store,project,iid)
                result=build_video(store,project,{'scope':'full'},'native',False,False,16,job_for(store,project))
                v=result['validation'];self.assertEqual(v['decoded_frames'],18);self.assertEqual(v['duration'],str(Fraction(18,fps)))
                self.assertEqual(v['cuts'],[str(Fraction(6,fps)),str(Fraction(12,fps))]);self.assertEqual(v['resolution'],[160,96]);self.assertTrue(v['complete_decode'])
                target.apply_corrections(work,{'1':encoded_mask(Image.new('L',(160,96)))})
                with self.assertRaises(ValueError):finish(work,root/'must-not-exist.zip')
                self.assertFalse((root/'must-not-exist.zip').exists())
